// Always wrap with retry on TransientTransactionError in production
// (drivers expose withTransaction() which retries automatically)
await session.withTransaction(async () => {
  await accounts.updateOne({ _id: a }, { $inc: { bal: -100 } }, { session });
  await accounts.updateOne({ _id: b }, { $inc: { bal:  100 } }, { session });
});

